import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const z=JSON.parse('{"title":"茅斋","description":"","frontmatter":{"title":"茅斋","date":"2026-11-11T00:00:00.000Z","seq":218,"categories":["美文","纳兰性德词"],"collection":"《纳兰性德词》","tags":["纳兰性德词","清"],"poem":true,"author":"纳兰性德","source_book":"纳兰性德词"},"headers":[],"relativePath":"blogs/纳兰性德词/茅斋.md","filePath":"blogs/纳兰性德词/茅斋.md"}'),o={name:"blogs/纳兰性德词/茅斋.md"};function c(l,a,n,m,r,_){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="茅斋" tabindex="-1">茅斋 <a class="header-anchor" href="#茅斋" aria-label="Permalink to &quot;茅斋&quot;">​</a></h1><p class="poem-meta">清 · 纳兰性德</p><div class="poem"><p class="poem-stanza">闲亭照白日，一室罗古今</p><p class="poem-stanza">偶焉此栖迟，抱膝悠然吟</p><p class="poem-stanza">吟罢有余适，散瞩复披襟</p><p class="poem-stanza">时开玉怀卷，或弹珠柱琴</p><p class="poem-stanza">檐树吐新花，枝头语珍禽</p><p class="poem-stanza">花发饶冶色，禽鸣多姣音</p><p class="poem-stanza">色冶眩春目，音姣伤春心</p><p class="poem-stanza">夕阳下虞渊，寂莫还空林</p><p class="poem-stanza">清光复相照，片月西山岭</p><p class="poem-stanza">东园桃李姿，是妾嫁君时</p><p class="poem-stanza">燕婉为夫妇，相爱不相离</p><p class="poem-stanza">良人忽远征，妾独守空帏</p><p class="poem-stanza">忧来恒自叹，冀死魂追随</p><p class="poem-stanza">又念妾死时，谁制万里衣</p><p class="poem-stanza">幸有双鲤鱼，拟为寄君辞</p><p class="poem-stanza">终日不成章，含泪自封题</p><p class="poem-stanza">君若得鲤鱼，剖鱼开素书</p><p class="poem-stanza">但看行中字，一一与泪俱</p></div>',3)])])}const d=s(o,[["render",c]]);export{z as __pageData,d as default};
